# Gera quebras.csv deste bloco (colunas das outras pastas). Le series/ e derivado/. python3 -I quebras.py
import csv, re, sys
from pathlib import Path
RAIZ = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(RAIZ / "scripts"))
import txt
COLS = "indicador,serie,data_quebra,tipo_de_quebra,metodo_antigo,metodo_novo,razao_declarada_pela_fonte,fonte_primaria_url,trecho_citado,direcao_do_efeito,como_a_direcao_foi_determinada,efeito_medido,como_medido,apresentada_como_aprimoramento".split(",")

def trecho(arq, rx, w=0, antes=0):
    f = RAIZ / arq
    t = re.sub(r"\s+", " ", txt.ler(f) if f.suffix in (".html", ".htm") else f.read_text())
    m = re.search(rx, t)
    assert m, (arq, rx)
    return t[max(0, m.start() - antes): m.end() + w].strip()

ctb = {}
for r in csv.DictReader(open(RAIZ / "series/receita-ctb-total-por-edicao.csv")):
    if any(x in r["definicao_linha"] for x in ("Fiscal", "Arrecadacao", "Liquida")):
        continue
    ctb.setdefault((int(r["indicador"].split("_")[-1]), int(r["ano"])), float(r["valor"]))
pa = {(int(r["edicao"]), int(r["ano"])): r for r in csv.DictReader(open(RAIZ / "derivado/ctb-pib-arrecadacao-por-edicao.csv"))}
def d(a, b):
    return "%+.2f p.p." % (b - a)
R = "https://www.gov.br/receitafederal/pt-br/centrais-de-conteudo/publicacoes/estudos/carga-tributaria/carga-tributaria-no-brasil-%d/@@download/file"
Q = []
def q(**k):
    Q.append({c: k.get(c, "") for c in COLS})

